select * from ai_question_info where is_del = 0


    and create_time between #{searchVo.startTime} and #{searchVo.endTime}


    and `content` like concat('%',#{searchVo.keyWord},'%')


    and `reply_type`  = #{searchVo.replyType}

order by `create_time` desc

select count(*) as total,reply_type  from ai_question_info  where is_del = 0

    and create_time between #{searchVo.startTime} and #{searchVo.endTime}

 group by reply_type
